import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

#define TILE_OH 32
#define TILE_OW 32
#define OC_TILE 8
#define C_CHUNK 4  // Halve per-block dynamic smem (39.3KB -> 19.2KB): profiler shows occupancy is smem-limited at 2 blocks/SM (33.3%); this allows 4 blocks/SM (register-limited), doubling theoretical occupancy while keeping the tiled structure identical.
#define THREADS 256

__global__ void conv2d_tiled_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch,
    const int in_channels,
    const int in_h,
    const int in_w,
    const int out_channels,
    const int kernel_h,
    const int kernel_w,
    const int out_h,
    const int out_w,
    const int stride,
    const int padding,
    const int dilation,
    const int oc_tiles,
    const int tile_in_h,
    const int tile_in_w) {
  extern __shared__ float smem[];
  float* s_in = smem;
  float* s_w = smem + C_CHUNK * tile_in_h * tile_in_w;

  const int tx = threadIdx.x & 15;
  const int ty = threadIdx.x >> 4;

  const int ow0 = blockIdx.x * TILE_OW + tx * 2;
  const int oh0 = blockIdx.y * TILE_OH + ty * 2;
  const int oc_tile = blockIdx.z % oc_tiles;
  const int n = blockIdx.z / oc_tiles;
  const int oc_base = oc_tile * OC_TILE;

  const bool valid_spatial = (oh0 < out_h) && (ow0 < out_w);

  float acc[2][2][OC_TILE];
#pragma unroll
  for (int dy = 0; dy < 2; ++dy) {
#pragma unroll
    for (int dx = 0; dx < 2; ++dx) {
#pragma unroll
      for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
        acc[dy][dx][oc_local] = 0.0f;
      }
    }
  }

  const int in_tile_elems = C_CHUNK * tile_in_h * tile_in_w;
  const int w_tile_elems = OC_TILE * C_CHUNK * kernel_h * kernel_w;
  const int kk = kernel_h * kernel_w;

  const int in_block_base_h = blockIdx.y * TILE_OH * stride - padding;
  const int in_block_base_w = blockIdx.x * TILE_OW * stride - padding;

  for (int c_base = 0; c_base < in_channels; c_base += C_CHUNK) {
    for (int idx = threadIdx.x; idx < in_tile_elems; idx += THREADS) {
      const int c_local = idx / (tile_in_h * tile_in_w);
      const int rem = idx - c_local * tile_in_h * tile_in_w;
      const int ih_local = rem / tile_in_w;
      const int iw_local = rem - ih_local * tile_in_w;

      const int c = c_base + c_local;
      const int ih = in_block_base_h + ih_local;
      const int iw = in_block_base_w + iw_local;

      float v = 0.0f;
      if (c < in_channels && ih >= 0 && ih < in_h && iw >= 0 && iw < in_w) {
        v = input[((n * in_channels + c) * in_h + ih) * in_w + iw];
      }
      s_in[idx] = v;
    }

    for (int idx = threadIdx.x; idx < w_tile_elems; idx += THREADS) {
      const int oc_local = idx / (C_CHUNK * kk);
      int rem = idx - oc_local * C_CHUNK * kk;
      const int c_local = rem / kk;
      rem -= c_local * kk;
      const int kh = rem / kernel_w;
      const int kw = rem - kh * kernel_w;

      const int oc = oc_base + oc_local;
      const int c = c_base + c_local;

      float v = 0.0f;
      if (oc < out_channels && c < in_channels) {
        v = weight[((oc * in_channels + c) * kernel_h + kh) * kernel_w + kw];
      }
      s_w[idx] = v;
    }

    __syncthreads();

    if (valid_spatial) {
      const int s_in_plane = tile_in_h * tile_in_w;
      for (int kh = 0; kh < kernel_h; ++kh) {
        const int ih_local0 = ty * 2 * stride + kh * dilation;
        if (ih_local0 >= tile_in_h) continue;
        const int row_off = stride * tile_in_w;
        for (int kw = 0; kw < kernel_w; ++kw) {
          const int iw_local0 = tx * 2 * stride + kw * dilation;
          if (iw_local0 >= tile_in_w) continue;
          const int s_in_base = ih_local0 * tile_in_w + iw_local0;
          for (int c_local = 0; c_local < C_CHUNK; ++c_local) {
            const int c_off = c_local * s_in_plane + s_in_base;
            const float xv00 = s_in[c_off];
            const float xv01 = s_in[c_off + stride];
            const float xv10 = s_in[c_off + row_off];
            const float xv11 = s_in[c_off + row_off + stride];
            const int s_w_base = (c_local * kernel_h + kh) * kernel_w + kw;
#pragma unroll
            for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
              const float wv = s_w[oc_local * C_CHUNK * kk + s_w_base];
              acc[0][0][oc_local] += xv00 * wv;
              acc[0][1][oc_local] += xv01 * wv;
              acc[1][0][oc_local] += xv10 * wv;
              acc[1][1][oc_local] += xv11 * wv;
            }
          }
        }
      }
    }

    __syncthreads();
  }

  if (valid_spatial) {
#pragma unroll
    for (int dy = 0; dy < 2; ++dy) {
      const int oh = oh0 + dy;
      if (oh >= out_h) continue;
#pragma unroll
      for (int dx = 0; dx < 2; ++dx) {
        const int ow = ow0 + dx;
        if (ow >= out_w) continue;
#pragma unroll
        for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
          const int oc = oc_base + oc_local;
          if (oc < out_channels) {
            float v = acc[dy][dx][oc_local];
            if (bias != nullptr) {
              v += bias[oc];
            }
            output[((n * out_channels + oc) * out_h + oh) * out_w + ow] = v;
          }
        }
      }
    }
  }
}

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups) {
  TORCH_CHECK(input.is_cuda(), "input must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
  TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
  TORCH_CHECK(input.dim() == 4, "input must be NCHW");
  TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
  TORCH_CHECK(groups == 1, "custom kernel currently supports groups == 1");

  const c10::cuda::CUDAGuard guard(input.device());

  auto x = input.contiguous();
  auto w = weight.contiguous();
  auto b = has_bias ? bias.contiguous() : bias;

  const int batch = static_cast<int>(x.size(0));
  const int in_channels = static_cast<int>(x.size(1));
  const int in_h = static_cast<int>(x.size(2));
  const int in_w = static_cast<int>(x.size(3));

  const int out_channels = static_cast<int>(w.size(0));
  TORCH_CHECK(w.size(1) == in_channels, "weight/input channel mismatch");
  const int kernel_h = static_cast<int>(w.size(2));
  const int kernel_w = static_cast<int>(w.size(3));

  const int out_h = static_cast<int>((in_h + 2 * padding - dilation * (kernel_h - 1) - 1) / stride + 1);
  const int out_w = static_cast<int>((in_w + 2 * padding - dilation * (kernel_w - 1) - 1) / stride + 1);
  TORCH_CHECK(out_h > 0 && out_w > 0, "invalid output size");

  auto out = torch::empty({batch, out_channels, out_h, out_w}, x.options());

  const int oc_tiles = (out_channels + OC_TILE - 1) / OC_TILE;
  const int tile_in_h = (TILE_OH - 1) * static_cast<int>(stride) + (kernel_h - 1) * static_cast<int>(dilation) + 1;
  const int tile_in_w = (TILE_OW - 1) * static_cast<int>(stride) + (kernel_w - 1) * static_cast<int>(dilation) + 1;

  const size_t smem_bytes =
      (static_cast<size_t>(C_CHUNK) * tile_in_h * tile_in_w +
       static_cast<size_t>(OC_TILE) * C_CHUNK * kernel_h * kernel_w) * sizeof(float);
  TORCH_CHECK(smem_bytes <= 48 * 1024, "shared memory limit exceeded for this configuration");

  dim3 block(THREADS);
  dim3 grid((out_w + TILE_OW - 1) / TILE_OW,
            (out_h + TILE_OH - 1) / TILE_OH,
            batch * oc_tiles);
  TORCH_CHECK(grid.z <= 65535, "grid.z too large");

  const float* bias_ptr = has_bias ? b.data_ptr<float>() : nullptr;

  conv2d_tiled_kernel<<<grid, block, smem_bytes, at::cuda::getCurrentCUDAStream()>>>(
      x.data_ptr<float>(),
      w.data_ptr<float>(),
      bias_ptr,
      out.data_ptr<float>(),
      batch,
      in_channels,
      in_h,
      in_w,
      out_channels,
      kernel_h,
      kernel_w,
      out_h,
      out_w,
      static_cast<int>(stride),
      static_cast<int>(padding),
      static_cast<int>(dilation),
      oc_tiles,
      tile_in_h,
      tile_in_w);

  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return out;
}
"""

_CPP_SRC = r"""
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups);
"""

_conv_cuda = load_inline(
    name="custom_conv2d_tiled",
    cpp_sources=[_CPP_SRC],
    cuda_sources=[_CUDA_SRC],
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None
            self.register_buffer("_empty_bias", torch.empty(0), persistent=False)

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (in_channels // groups) * kernel_size * kernel_size
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias_arg = self.bias if self.bias is not None else self._empty_bias
        return _conv_cuda.conv2d_forward(
            x,
            self.weight,
            bias_arg,
            self.use_bias,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
        )

